Use `pg` (node-postgres) with `Pool`:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT ?? '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                  // max connections in pool
  min: 2,                   // keep alive connections
  idleTimeoutMillis: 30000, // close idle connections after 30s
  connectionTimeoutMillis: 5000, // fail fast if no connection available in 5s

  // Keep connections alive
  keepAlive: true,
  keepAliveInitialDelayMillis: 10000,
});

// Error on idle client — must handle or process crashes
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});
```

**Query wrapper with proper release:**

```javascript
async function query(text, params) {
  const start = Date.now();
  const client = await pool.connect(); // throws if connectionTimeoutMillis exceeded
  try {
    const result = await client.query(text, params);
    return result;
  } finally {
    client.release(); // always release, even on error
  }
}
```

**Transaction helper:**

```javascript
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Graceful shutdown:**

```javascript
process.on('SIGTERM', async () => {
  await pool.end(); // drain pool, reject new connections
  process.exit(0);
});
```

Key points:
- `pool.connect()` + `client.release()` for transactions; `pool.query()` for one-shots (auto-releases)
- `pool.on('error')` **required** — unhandled error on idle client crashes process
- `connectionTimeoutMillis` controls queue wait, not query duration — set query timeout separately with `SET statement_timeout`
- `max: 20` typical default; tune to `(CPU cores * 2) + disk spindles` or Postgres `max_connections / num_app_instances`
